'use client'

import { useState } from 'react'
import Navigation from '../components/Navigation'

// Sample gig data
const sampleGigs = [
  {
    id: 1,
    title: "Indie Night at The Basement",
    artist: "The Local Band",
    venue: "The Basement",
    date: "2024-01-15",
    time: "8:00 PM",
    genre: "Indie Rock",
    price: "$15",
    image: "https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=400&h=300&fit=crop",
    location: "Downtown"
  },
  {
    id: 2,
    title: "Jazz Fusion Evening",
    artist: "Smooth Collective",
    venue: "Blue Note Cafe",
    date: "2024-01-16",
    time: "7:30 PM",
    genre: "Jazz",
    price: "$20",
    image: "https://images.unsplash.com/photo-1516280440614-37939bbacd81?w=400&h=300&fit=crop",
    location: "Midtown"
  },
  {
    id: 3,
    title: "Acoustic Night",
    artist: "Sarah & The Strings",
    venue: "Coffee House",
    date: "2024-01-17",
    time: "6:00 PM",
    genre: "Folk",
    price: "Free",
    image: "https://images.unsplash.com/photo-1508700115892-45ecd05ae2ad?w=400&h=300&fit=crop",
    location: "University District"
  },
  {
    id: 4,
    title: "Electronic Beats",
    artist: "Digital Dreams",
    venue: "Warehouse Club",
    date: "2024-01-18",
    time: "10:00 PM",
    genre: "Electronic",
    price: "$25",
    image: "https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?w=400&h=300&fit=crop",
    location: "Industrial Zone"
  }
]

export default function GigsPage() {
  const [selectedGenre, setSelectedGenre] = useState('all')
  const [searchTerm, setSearchTerm] = useState('')

  const filteredGigs = sampleGigs.filter(gig => {
    const matchesGenre = selectedGenre === 'all' || gig.genre === selectedGenre
    const matchesSearch = gig.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         gig.artist.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         gig.venue.toLowerCase().includes(searchTerm.toLowerCase())
    return matchesGenre && matchesSearch
  })

  const genres = ['all', ...new Set(sampleGigs.map(gig => gig.genre))]

  return (
    <div className="min-h-screen bg-gray-50">
      <Navigation />

      {/* Header */}
      <div className="bg-gradient-to-r from-purple-600 to-blue-600">
        <div className="max-w-7xl mx-auto py-16 px-4 sm:py-24 sm:px-6 lg:px-8">
          <div className="text-center">
            <h1 className="text-4xl font-extrabold text-white sm:text-5xl md:text-6xl">
              Discover Local Gigs
            </h1>
            <p className="mt-3 max-w-md mx-auto text-base text-purple-100 sm:text-lg md:mt-5 md:text-xl md:max-w-3xl">
              Find the best local music events, from indie bands to jazz ensembles
            </p>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <input
              type="text"
              placeholder="Search gigs, artists, or venues..."
              className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-purple-500 focus:border-purple-500"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="sm:w-48">
            <select
              className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-purple-500 focus:border-purple-500"
              value={selectedGenre}
              onChange={(e) => setSelectedGenre(e.target.value)}
            >
              {genres.map(genre => (
                <option key={genre} value={genre}>
                  {genre === 'all' ? 'All Genres' : genre}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Gigs Grid */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-12">
        {filteredGigs.length === 0 ? (
          <div className="text-center py-12">
            <h3 className="text-lg font-medium text-gray-900">No gigs found</h3>
            <p className="mt-2 text-gray-500">Try adjusting your search or filters</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredGigs.map((gig) => (
              <div key={gig.id} className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow">
                <div className="aspect-w-16 aspect-h-9">
                  <img
                    src={gig.image}
                    alt={gig.title}
                    className="w-full h-48 object-cover"
                  />
                </div>
                <div className="p-6">
                  <div className="flex items-center justify-between mb-2">
                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-purple-100 text-purple-800">
                      {gig.genre}
                    </span>
                    <span className="text-sm text-gray-500">{gig.location}</span>
                  </div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-1">{gig.title}</h3>
                  <p className="text-sm text-gray-600 mb-2">{gig.artist}</p>
                  <p className="text-sm text-gray-500 mb-3">{gig.venue}</p>
                  <div className="flex items-center justify-between">
                    <div className="text-sm text-gray-500">
                      <p>{new Date(gig.date).toLocaleDateString()}</p>
                      <p>{gig.time}</p>
                    </div>
                    <span className="text-lg font-semibold text-purple-600">{gig.price}</span>
                  </div>
                  <button className="mt-4 w-full bg-purple-600 text-white py-2 px-4 rounded-md hover:bg-purple-700 transition-colors">
                    View Details
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
} 